  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      merchantSigner: getNextAccount(),
      passport: getNextAccount(),
      depositAccount: getNextAccount(),
      merchant: getNextAccount(),
      rentalLock: getNextAccount(),
    },
    data: getRecordReturnInstructionDataDecoder().decode(instruction.data),
  };
